                "        if (revision !== request.revision || head !== revision)",
                "          throw new GraphPreparationError({",
                "            reason: \"invalid-target\",",
                "            message: \"Snapshot preparation requires HEAD to be the requested commit.\",",
                "          });",
                "        const tree = fullRevision(",
                "          await git([\"rev-parse\", \"--verify\", `${revision}^{tree}`], \"git_tree\", \"Git tree resolution\"),",
                "          \"snapshot tree\",",
                "        );",
