                "        if (!(frozen.provider.capabilities.relationSupportByProfile[\"full\"] ?? []).length)",
                "          throw new GraphPreparationError({",
                "            reason: \"unsupported-provider\",",
                "            message: \"Graph provider does not declare a full profile.\",",
                "          });",
                "        const receipt = await graphCommand(",
                "          frozen.executable,",
                "          [\"index\", \"--repo\", repository, \"--head\", \"--profile\", \"full\", \"--format\", \"json\"],",
