                "          recorder,",
                "          \"Graph snapshot preparation\",",
                "        );",
                "        let parsed: ReturnType<typeof parseSnapshotPreparation>;",
                "        try {",
                "          parsed = parseSnapshotPreparation(receipt, repository, revision, tree, frozen.provider.version);",
