                "          profile: \"full\",",
                "          cache: parsed.cache,",
                "          ...(parsed.store === undefined ? {} : { store: parsed.store }),",
                "          counts: parsed.counts,",
                "        };",
                "      } finally {",
                "        await rm(temporaryRoot, { recursive: true, force: true });"
